  "description": "Given an initial weight and a target weight, determine the optimal sequence of Auger activations to reach the target weight in the shortest possible time while ensuring the final weight is within a strict tolerance and avoiding system blockages.",
  "objective": {
    "goal": "Minimize total time",
    "formula": "Minimize Σ ΔTimestamp for the duration of the filling process until WeightSensor.I_uiValue reaches the target weight."
  },
  "decision_variables": {
    "variable": "Auger.O_xOn",
    "type": "Binary sequence",
    "description": "A time-indexed sequence of activations (0 or 1) for the Auger actuator."
  },
  "constraints": [
    {
      "constraint": "Weight Accuracy",
      "description": "The final value of WeightSensor.I_uiValue must be within a specified tolerance (e.g., ±0.5%) of the target weight to avoid overfilling or underfilling."
    },
    {
      "constraint": "Blockage Avoidance",
      "description": "The sequence of Auger.O_xOn activations must be optimized such that FunnelBlocked.I_xSignal never equals 1, preventing system downtime."
    },
    {
      "constraint": "Filling Rate Dynamics",
      "description": "The increase in WeightSensor.I_uiValue is constrained by the filling rate (calculated as the derivative of WeightSensor.I_uiValue with respect to Timestamp when Auger.O_xOn = 1)."
    },
    {
      "constraint": "Actuator Mechanical Limits",
      "description": "Minimum and maximum continuous activation times for Auger.O_xOn to prevent mechanical wear and tear on the motor."
    }
  ]
}
