{
  "model_formulation": {
    "description": "MILP model to optimize the filling sequence of an Auger system to reach a target weight in minimum time while respecting mechanical limits and avoiding system blockages.",
    "sets": {
      "T": "Set of time steps {0, 1, ..., T_max}, where T_max is the maximum allowable time horizon."
    },
    "parameters": {
      "W_target": "Target weight to be reached (WeightSensor.I_uiValue).",
      "epsilon": "Allowable tolerance for the final weight (e.g., 0.5% of W_target).",
      "R": "Filling rate: the weight increase per time step when the Auger is active (calculated from historical data of WeightSensor.I_uiValue vs Timestamp).",
      "W_0": "Initial weight at t=0.",
      "T_min": "Minimum continuous activation time for the Auger to prevent mechanical wear.",
      "T_max_act": "Maximum continuous activation time for the Auger to prevent mechanical wear.",
      "B_t": "Blockage signal at time t (FunnelBlocked.I_xSignal), where B_t = 1 indicates a blockage.",
      "M": "A large positive constant (Big-M) used for logical constraints."
    },
    "decision_variables": {
      "x_t": "Binary variable: 1 if Auger.O_xOn is active at time t, 0 otherwise. {x_t ∈ {0, 1} | t ∈ T}",
      "w_t": "Continuous variable: WeightSensor.I_uiValue at time t. {w_t ∈ ℝ | t ∈ T}",
      "z_t": "Binary variable: 1 if the target weight has been reached by time t, 0 otherwise. {z_t ∈ {0, 1} | t ∈ T}"
    },
    "objective_function": {
      "goal": "Minimize total time to reach the target weight",
      "formula": "Minimize \\sum_{t=0}^{T_{max}} (1 - z_t)"
    },
    "constraints": [
      {
        "name": "Weight Accumulation Dynamics",
        "formula": "w_{t+1} = w_t + R \\cdot x_t, \\quad \\forall t \\in \{0, ..., T_{max}-1\\}",
        "description": "The weight at the next time step is the current weight plus the filling rate multiplied by the Auger state."
      },
      {
        "name": "Initial Weight",
        "formula": "w_0 = W_0",
        "description": "Sets the starting weight of the process."
      },
      {
        "name": "Target Weight Reach Condition",
        "formula": [
          "w_t \\ge W_{target} - \\epsilon - M(1 - z_t), \\quad \\forall t \\in T",
          "w_t \\le W_{target} + \\epsilon + M(1 - z_t), \\quad \\forall t \\in T"
        ],
        "description": "z_t can only be 1 if the weight w_t is within the tolerance range [W_target - epsilon, W_target + epsilon]."
      },
      {
        "name": "Completion Monotonicity",
        "formula": "z_t \\ge z_{t-1}, \\quad \\forall t \\in \{1, ..., T_{max}\\}",
        "description": "Once the target weight is reached (z_t = 1), the process remains in the completed state."
      },
      {
        "name": "Blockage Avoidance",
        "formula": "x_t \\le 1 - B_t, \\quad \\forall t \\in T",
        "description": "The Auger cannot be active (x_t = 1) if the funnel is blocked (B_t = 1)."
      },
      {
        "name": "Minimum Continuous Activation",
        "formula": "x_k \\ge x_t - x_{t-1}, \\quad \\forall t \\in \{1, ..., T_{max}\\}, \\forall k \\in \{t, ..., t + T_{min} - 1\\}",
        "description": "If the Auger is switched on at time t, it must remain on for at least T_min consecutive steps."
      },
      {
        "name": "Maximum Continuous Activation",
        "formula": "\\sum_{k=t}^{t + T_{max\_act}} x_k \\le T_{max\_act}, \\quad \\forall t \\in \{0, ..., T_{max} - T_{max\_act}\\}",
        "description": "The Auger cannot be active for more than T_max_act consecutive time steps."
      }
    ]
  }
}
```

